# Generated by build.py from recipe.yml for recipe http-lock-out-one-account. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site2', 'site3' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site2/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site3/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'token.txt'), "control-token-0123456789abcdefghij")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--user', 'alice:a1-secret', '--user', 'bob:b2-secret', '--fault', '"refuse-login;account=bob"', '--control', 'http://127.0.0.1:8082', '--control-token-file', 'token.txt', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o NUL -w "%{http_code}\n" --digest -u alice:a1-secret http://127.0.0.1:8080/hello.txt --next -s -o NUL -w "%{http_code}\n" --digest -u bob:b2-secret http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
